/// <reference types="audioworklet" />

const hasPerformanceApi =
  typeof performance !== 'undefined' && typeof performance.now === 'function';

function getTimeMs(): number {
  if (hasPerformanceApi) {
    return performance.now();
  }
  return (globalThis as unknown as { currentTime: number }).currentTime * 1000;
}

interface WebAssemblyInstantiatedSource {
  instance: WebAssembly.Instance;
  module: WebAssembly.Module;
}

function instantiateWasmModule(
  bytes: ArrayBuffer,
  imports: WebAssembly.Imports,
): Promise<WebAssemblyInstantiatedSource> {
  return WebAssembly.instantiate(bytes, imports) as Promise<WebAssemblyInstantiatedSource>;
}

interface IAudioDenoiser {
  readonly type: string;
  readonly name: string;
  readonly frameSize: number;
  readonly isInitialized: boolean;
  initialize(): Promise<void>;
  processFrame(frame: Float32Array): number;
  getLastVadScore(): number;
  destroy(): void;
}

interface DenoiseProcessorOptions {
  denoiserType?: string;
  debug?: boolean;
}

interface EcprtDenoiserWasmData {
  wasmJsCode: string;
  wasmBinary: Uint8Array;
  isSimd?: boolean;
}

type DenoiserWasmData = EcprtDenoiserWasmData;

interface EcprtDenoiserModule {
  _rnnoise_get_frame_size(): number;
  _rnnoise_create(model?: number): number;
  _rnnoise_destroy(state: number): void;
  _rnnoise_process_frame(state: number, output: number, input: number): number;
  _malloc(size: number): number;
  _free(ptr: number): void;
  HEAPF32: Float32Array;
}

const F32_BYTE_SIZE = 4;
const INT16_SCALE = 0x7fff;

class EcprtDenoiserWorkletProcessor implements IAudioDenoiser {
  readonly type = 'ecprt-denoiser';
  readonly name: string;
  frameSize = 480;
  private _isInitialized = false;
  private module: EcprtDenoiserModule | null = null;
  private state = 0;
  private pcmInputPtr = 0;
  private pcmOutputPtr = 0;
  private lastVad = 0;
  private debug: boolean;

  constructor(
    private wasmJsCode: string,
    private wasmBinary: Uint8Array,
    private isSimd: boolean = false,
    debug: boolean = false,
  ) {
    this.name = isSimd ? 'ECPRT Denoiser (SIMD)' : 'ECPRT Denoiser';
    this.debug = debug;
    if (this.debug) {
      console.log('[EcprtDenoiserWorklet] Constructor:', {
        wasmBinarySize: wasmBinary.byteLength,
        isSimd,
      });
    }
  }

  get isInitialized(): boolean {
    return this._isInitialized;
  }

  async initialize(): Promise<void> {
    if (this.debug) {
      console.log('[EcprtDenoiserWorklet] Initializing...');
    }

    let jsCode = this.wasmJsCode;
    jsCode = jsCode.replace(/export\s+default\s+Module\s*;?\s*$/g, '');
    jsCode = jsCode.replace(/export\s+default\s+createRNNoiseModule\s*;?\s*$/g, '');
    jsCode = jsCode.replace(/import\.meta\.url/g, '""');
    jsCode = jsCode.replace(/new\s+URL\s*\(\s*["']([^"']+)["']\s*,\s*[^)]+\)\.href/g, '"$1"');

    const wasmBinary = this.wasmBinary;

    let createModule: (options: Record<string, unknown>) => Promise<EcprtDenoiserModule>;

    try {
      // eslint-disable-next-line no-eval
      createModule = (0, eval)(
        `(function() { ${jsCode}; return typeof Module !== 'undefined' ? Module : (typeof createRNNoiseModule !== 'undefined' ? createRNNoiseModule : createRnnoiseModule); })()`,
      );
    } catch (e) {
      console.error('[EcprtDenoiserWorklet] Failed to eval JS code:', e);
      throw e;
    }

    if (this.debug) {
      console.log('[EcprtDenoiserWorklet] Creating module...');
    }

    this.module = (await createModule({
      wasmBinary: wasmBinary.buffer,
      instantiateWasm: (
        imports: WebAssembly.Imports,
        successCallback: (instance: WebAssembly.Instance) => void,
      ) => {
        instantiateWasmModule(wasmBinary.buffer as ArrayBuffer, imports)
          .then((result) => successCallback(result.instance))
          .catch((err) => console.error('[EcprtDenoiserWorklet] WASM instantiation failed:', err));
        return {};
      },
    })) as EcprtDenoiserModule;

    this.frameSize = this.module._rnnoise_get_frame_size();
    this.state = this.module._rnnoise_create(0);

    if (!this.state) {
      throw new Error('ECPRT Denoiser create failed');
    }

    this.pcmInputPtr = this.module._malloc(this.frameSize * F32_BYTE_SIZE);
    this.pcmOutputPtr = this.module._malloc(this.frameSize * F32_BYTE_SIZE);

    if (!this.pcmInputPtr || !this.pcmOutputPtr) {
      this.destroy();
      throw new Error('Failed to allocate ECPRT Denoiser buffers');
    }

    this._isInitialized = true;

    if (this.debug) {
      console.log('[EcprtDenoiserWorklet] Initialized:', {
        frameSize: this.frameSize,
        state: this.state,
        pcmInputPtr: this.pcmInputPtr,
        pcmOutputPtr: this.pcmOutputPtr,
      });
    }
  }

  processFrame(frame: Float32Array): number {
    if (!this.module || !this.state) return 0;

    const inputIndex = this.pcmInputPtr / F32_BYTE_SIZE;
    const outputIndex = this.pcmOutputPtr / F32_BYTE_SIZE;

    for (let i = 0; i < this.frameSize; i++) {
      this.module.HEAPF32[inputIndex + i] = frame[i] * INT16_SCALE;
    }

    this.lastVad = this.module._rnnoise_process_frame(
      this.state,
      this.pcmOutputPtr,
      this.pcmInputPtr,
    );

    for (let i = 0; i < this.frameSize; i++) {
      frame[i] = this.module.HEAPF32[outputIndex + i] / INT16_SCALE;
    }

    return this.lastVad;
  }

  getLastVadScore(): number {
    return this.lastVad;
  }

  destroy(): void {
    if (this.debug) {
      console.log('[EcprtDenoiserWorklet] Destroying...');
    }

    if (this.module) {
      if (this.state) this.module._rnnoise_destroy(this.state);
      if (this.pcmInputPtr) this.module._free(this.pcmInputPtr);
      if (this.pcmOutputPtr) this.module._free(this.pcmOutputPtr);
    }
    this.module = null;
    this.state = 0;
    this.pcmInputPtr = 0;
    this.pcmOutputPtr = 0;
    this._isInitialized = false;

    if (this.debug) {
      console.log('[EcprtDenoiserWorklet] Destroyed');
    }
  }
}

interface WorkletProcessorOptions {
  processorOptions?: {
    filterOpts?: DenoiseProcessorOptions;
    wasmData?: DenoiserWasmData;
  };
}

/**
 * Simple ring buffer for audio samples.
 * This simpler approach avoids the audio cuts caused by complex warmup/fade logic.
 */
class SimpleRingBuffer {
  private buffer: Float32Array;
  private writeIndex = 0;
  private readIndex = 0;
  private _length = 0;
  private capacity: number;

  constructor(capacity: number) {
    this.capacity = capacity;
    this.buffer = new Float32Array(capacity);
  }

  get length(): number {
    return this._length;
  }

  write(samples: Float32Array): void {
    for (let i = 0; i < samples.length; i++) {
      if (this._length < this.capacity) {
        this.buffer[this.writeIndex] = samples[i];
        this.writeIndex = (this.writeIndex + 1) % this.capacity;
        this._length++;
      }
    }
  }

  read(dest: Float32Array, offset: number, count: number): number {
    const toRead = Math.min(count, this._length);
    for (let i = 0; i < toRead; i++) {
      dest[offset + i] = this.buffer[this.readIndex];
      this.readIndex = (this.readIndex + 1) % this.capacity;
    }
    this._length -= toRead;
    return toRead;
  }

  clear(): void {
    this.writeIndex = 0;
    this.readIndex = 0;
    this._length = 0;
  }
}

class DenoiseWorkletProcessor extends AudioWorkletProcessor {
  private processor?: IAudioDenoiser;
  private isProcessorInitialized = false;
  private isEnabled = true;
  private frameSize = 480;
  private destroyed = false;
  private debugLogs: boolean;
  private filterOptions: DenoiseProcessorOptions;
  private wasmData?: DenoiserWasmData;

  // Simple buffer management - key to avoiding audio cuts
  private inputBuffer: Float32Array;
  private inputBufferCount = 0;
  private outputBuffer: SimpleRingBuffer;
  private processCallCount = 0;
  private lastLogTime = 0;

  constructor(options?: WorkletProcessorOptions) {
    super();
    this.filterOptions = options?.processorOptions?.filterOpts ?? {};
    this.debugLogs = this.filterOptions.debug ?? false;
    this.wasmData = options?.processorOptions?.wasmData;

    this.inputBuffer = new Float32Array(480);
    this.outputBuffer = new SimpleRingBuffer(4800);

    // Always log constructor (important for debugging)
    console.log('[DenoiseWorklet] Constructor called with options:', {
      hasWasmData: !!this.wasmData,
      debug: this.debugLogs,
      filterOptions: this.filterOptions,
    });

    this.initializeProcessor();
    this.setupMessageHandler();
  }

  private async initializeProcessor(): Promise<void> {
    console.log('[DenoiseWorklet] initializeProcessor() starting...', {
      hasWasmData: !!this.wasmData,
    });

    if (!this.wasmData) {
      console.warn(
        '[DenoiseWorklet] No WASM data provided. Running in PASSTHROUGH mode - audio will not be processed!',
      );
      this.port.postMessage({
        type: 'PROCESSOR_ERROR',
        error: 'No WASM data - passthrough mode',
      });
      return;
    }

    try {
      console.log('[DenoiseWorklet] Creating processor...');
      this.processor = this.createProcessor(this.wasmData);

      console.log('[DenoiseWorklet] Initializing processor...');
      await this.processor.initialize();

      this.frameSize = this.processor.frameSize;
      this.inputBuffer = new Float32Array(this.frameSize);
      this.inputBufferCount = 0;

      this.outputBuffer = new SimpleRingBuffer(this.frameSize * 10);

      this.isProcessorInitialized = true;

      const initInfo = {
        name: this.processor.name,
        processorType: this.processor.type,
        frameSize: this.frameSize,
        isInitialized: this.isProcessorInitialized,
      };

      console.log('[DenoiseWorklet] Processor initialized successfully:', initInfo);

      this.port.postMessage({
        type: 'PROCESSOR_INITIALIZED',
        name: initInfo.name,
        processorType: initInfo.processorType,
        frameSize: initInfo.frameSize,
        isInitialized: initInfo.isInitialized,
      });
    } catch (error) {
      console.error('[DenoiseWorklet] Processor initialization FAILED:', error);
      this.port.postMessage({
        type: 'PROCESSOR_ERROR',
        error: String(error),
      });
    }
  }

  private createProcessor(data: DenoiserWasmData): IAudioDenoiser {
    const isSimd = 'isSimd' in data ? data.isSimd : false;
    console.log('[DenoiseWorklet] Creating ECPRT Denoiser processor:', {
      wasmJsCodeLength: data.wasmJsCode?.length,
      wasmBinarySize: data.wasmBinary?.byteLength,
      isSimd,
    });
    return new EcprtDenoiserWorkletProcessor(
      data.wasmJsCode,
      data.wasmBinary,
      isSimd,
      true, // Always enable debug logs in processor
    );
  }

  private setupMessageHandler(): void {
    console.log('[DenoiseWorklet] Setting up message handler');

    this.port.onmessage = (event: MessageEvent) => {
      console.log('[DenoiseWorklet] Message received:', event.data.type, event.data);

      if (event.data.type === 'DESTROY') {
        console.log('[DenoiseWorklet] Received DESTROY message');
        this.destroy();
      } else if (event.data.type === 'SET_ENABLED') {
        const wasEnabled = this.isEnabled;
        this.isEnabled = event.data.enabled;

        console.log('[DenoiseWorklet] SET_ENABLED:', {
          enabled: this.isEnabled,
          wasEnabled,
          isProcessorInitialized: this.isProcessorInitialized,
        });

        if (this.isEnabled && !wasEnabled) {
          this.resetBuffers();
        }
      }
    };
  }

  private resetBuffers(): void {
    console.log('[DenoiseWorklet] Resetting buffers...');
    this.inputBufferCount = 0;
    this.outputBuffer.clear();
    console.log('[DenoiseWorklet] Buffers reset completed');
  }

  /**
   * Main audio processing function.
   * Uses a simple, reliable approach without complex warmup/fade logic
   * that was causing audio cuts in the previous implementation.
   */
  process(inputs: Float32Array[][], outputs: Float32Array[][]): boolean {
    if (this.destroyed) return false;

    const input = inputs[0]?.[0];
    const output = outputs[0]?.[0];
    if (!input || !output) return true;

    this.processCallCount++;

    // Log first call for debugging
    if (this.processCallCount === 1) {
      console.log('[DenoiseWorklet] First process() call:', {
        inputLength: input.length,
        outputLength: output.length,
        isEnabled: this.isEnabled,
        isProcessorInitialized: this.isProcessorInitialized,
        hasProcessor: !!this.processor,
      });
    }

    // Passthrough mode when processor is not ready or disabled
    if (!this.isEnabled || !this.isProcessorInitialized || !this.processor) {
      output.set(input);

      // Log passthrough mode periodically
      if (this.processCallCount === 1 || this.processCallCount % 1000 === 0) {
        console.log('[DenoiseWorklet] PASSTHROUGH mode active:', {
          processCallCount: this.processCallCount,
          isEnabled: this.isEnabled,
          isProcessorInitialized: this.isProcessorInitialized,
          hasProcessor: !!this.processor,
        });
      }
      return true;
    }

    // Process input samples - accumulate until we have a full frame
    let inputOffset = 0;
    while (inputOffset < input.length) {
      const spaceInBuffer = this.frameSize - this.inputBufferCount;
      const samplesToAdd = Math.min(spaceInBuffer, input.length - inputOffset);

      for (let i = 0; i < samplesToAdd; i++) {
        this.inputBuffer[this.inputBufferCount + i] = input[inputOffset + i];
      }

      this.inputBufferCount += samplesToAdd;
      inputOffset += samplesToAdd;

      // Process when we have a complete frame
      if (this.inputBufferCount === this.frameSize) {
        this.processor.processFrame(this.inputBuffer);
        this.outputBuffer.write(this.inputBuffer);
        this.inputBufferCount = 0;
      }
    }

    // Output processed samples - simple approach without complex fade logic
    if (this.outputBuffer.length >= output.length) {
      this.outputBuffer.read(output, 0, output.length);
    } else if (this.outputBuffer.length > 0) {
      // Output what we have, fill rest with zeros (initial buffer filling)
      const available = this.outputBuffer.length;
      this.outputBuffer.read(output, 0, available);
      for (let i = available; i < output.length; i++) {
        output[i] = 0;
      }
    } else {
      // No output available yet (initial frames), output silence
      output.fill(0);
    }

    // Log stats periodically (every 5 seconds)
    const now = getTimeMs();
    if (now - this.lastLogTime > 5000) {
      console.log('[DenoiseWorklet] Processing stats:', {
        processCallCount: this.processCallCount,
        inputBufferCount: this.inputBufferCount,
        outputBufferLength: this.outputBuffer.length,
        frameSize: this.frameSize,
        isEnabled: this.isEnabled,
        processorName: this.processor?.name,
      });
      this.lastLogTime = now;
    }

    return true;
  }

  private destroy(): void {
    if (this.destroyed) return;

    console.log('[DenoiseWorklet] destroy() called:', {
      processCallCount: this.processCallCount,
      wasEnabled: this.isEnabled,
      wasInitialized: this.isProcessorInitialized,
    });

    this.port.postMessage({
      type: 'DESTROYED',
      finalStats: {
        processCallCount: this.processCallCount,
      },
    });

    this.destroyed = true;
    this.processor?.destroy();
    this.outputBuffer.clear();

    console.log('[DenoiseWorklet] Destroyed successfully');
  }
}

registerProcessor('DenoiseWorklet', DenoiseWorkletProcessor);
